struct ipv6_rt_hdr *ip6_rthdr_dup(struct ipv6_rt_hdr *src, gfp_t gfp,
                                  unsigned int *mtu, int *maxfraglen,
                                  unsigned int fragheaderlen,
                                  struct sk_buff *skb, struct rt6_info *rt,
                                  bool pmtuprobe) {
    if (!src) {
        return NULL;
    }

    struct ipv6_rt_hdr *dup = kmemdup(src, sizeof(*src), gfp);
    if (!dup) {
        return NULL;
    }

    if (pmtuprobe) {
        *mtu = IPV6_MTU - fragheaderlen;
        *maxfraglen = IPV6_MAX_MTU - fragheaderlen;
    }

    return dup;
}

struct ipv6_rt_hdr *ip6_rthdr_dup(struct ipv6_rt_hdr *src, gfp_t gfp,
                                  unsigned int *mtu, int *maxfraglen,
                                  unsigned int fragheaderlen,
                                  struct sk_buff *skb, struct rt6_info *rt,
                                  bool pmtuprobe)
{
    if (!src)
        return NULL;

    struct ipv6_rt_hdr *dup = kmemdup(src, src->hdrlen * 8, gfp);
    if (!dup)
        return NULL;

    if (pmtuprobe && skb && rt) {
        unsigned int new_mtu = ipv6_skb_dst_mtu(skb);
        if (new_mtu < *mtu) {
            *mtu = new_mtu;
            *maxfraglen = *mtu - fragheaderlen;
        }
    }

    return dup;
}

